//! XID_Start, XID_Continue and `str.isidentifier`, as CPython 3.13 answers
//! them over Unicode 15.1.0.
//!
//! The ranges in `xid_tables.rs` are generated by
//! `native/tools/gen_unicode_tables.py` from the interpreter's own
//! `str.isidentifier`: a code point is XID_Start when it is an identifier
//! alone and is not `_`, and XID_Continue when `"a"` followed by it is one.
//! `_` is not XID_Start; `str.isidentifier` accepts it first by name
//! (`Objects/unicodeobject.c`, `_PyUnicode_ScanIdentifier`). No NFKC
//! normalization is applied: `str.isidentifier` applies none, unlike the
//! compiler. A surrogate is neither.

#[rustfmt::skip]
#[allow(clippy::all)]
#[path = "xid_tables.rs"]
mod xid_tables;

use xid_tables::{XID_CONTINUE, XID_START};

fn in_ranges(ranges: &[(u32, u32)], cp: u32) -> bool {
    let i = ranges.partition_point(|&(start, _)| start <= cp);
    i > 0 && cp <= ranges[i - 1].1
}

/// XID_Start of one code point (without `_`). A value past U+10FFFF is
/// neither start nor continue.
pub fn is_xid_start(cp: u32) -> bool {
    if cp < 0x80 {
        return (cp as u8).is_ascii_alphabetic();
    }
    in_ranges(XID_START, cp)
}

/// XID_Continue of one code point.
pub fn is_xid_continue(cp: u32) -> bool {
    if cp < 0x80 {
        let b = cp as u8;
        return b.is_ascii_alphanumeric() || b == b'_';
    }
    in_ranges(XID_CONTINUE, cp)
}

/// `str.isidentifier` of a string given as code points: not empty, the
/// first XID_Start or `_`, every other XID_Continue.
pub fn is_identifier(text: &[u32]) -> bool {
    match text.split_first() {
        None => false,
        Some((&first, rest)) => {
            (first == u32::from(b'_') || is_xid_start(first))
                && rest.iter().all(|&cp| is_xid_continue(cp))
        }
    }
}
